  1 | /**
  2 |  * 🦙 Llama Player — DriveBrowser Component
  3 |  *
  4 |  * Componente para navegar no Google Drive, listar pastas e arquivos
  5 |  * de áudio, e adicioná-los à playlist.
  6 |  */
  7 | 
  8 | import { useState, useCallback } from "react";
  9 | import { useGoogleDrive } from "../hooks/useGoogleDrive";
 10 | import type { DriveFile, DriveFolder } from "../services/googleDrive";
 11 | import { isAudioFile } from "../services/googleDrive";
 12 | import type { Track } from "../types";
 13 | 
 14 | interface DriveBrowserProps {
 15 |   onAddTracks: (tracks: Track[]) => void;
 16 |   disabled?: boolean;
 17 | }
 18 | 
 19 | export function DriveBrowser({ onAddTracks, disabled = false }: DriveBrowserProps) {
 20 |   const {
 21 |     state,
 22 |     login,
 23 |     logout,
 24 |     navigateToFolder,
 25 |     navigateToBreadcrumb,
 26 |     goUp,
 27 |     driveFilesToTracks,
 28 |     searchAudio,
 29 |     CLIENT_ID,
 30 |   } = useGoogleDrive();
 31 | 
 32 |   const [searchQuery, setSearchQuery] = useState("");
 33 |   const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set());
 34 |   const [isAdding, setIsAdding] = useState(false);
 35 | 
 36 |   /**
 37 |    * Alterna seleção de um arquivo.
 38 |    */
 39 |   const toggleSelect = useCallback((fileId: string) => {
 40 |     setSelectedFiles((prev) => {
 41 |       const next = new Set(prev);
 42 |       if (next.has(fileId)) {
 43 |         next.delete(fileId);
 44 |       } else {
 45 |         next.add(fileId);
 46 |       }
 47 |       return next;
 48 |     });
 49 |   }, []);
 50 | 
 51 |   /**
 52 |    * Adiciona arquivos selecionados à playlist.
 53 |    */
 54 |   const handleAddSelected = useCallback(async () => {
 55 |     const audioFiles = state.items.filter(
 56 |       (item): item is DriveFile => isAudioFile(item) && selectedFiles.has(item.id)
 57 |     );
 58 | 
 59 |     if (audioFiles.length === 0) return;
 60 | 
 61 |     setIsAdding(true);
 62 |     try {
 63 |       const tracks = driveFilesToTracks(audioFiles);
 64 |       onAddTracks(tracks);
 65 |       setSelectedFiles(new Set());
 66 |     } catch (err) {
 67 |       console.error("[Llama Player] Erro ao adicionar tracks do Drive:", err);
 68 |     } finally {
 69 |       setIsAdding(false);
 70 |     }
 71 |   }, [state.items, selectedFiles, driveFilesToTracks, onAddTracks]);
 72 | 
 73 |   /**
 74 |    * Adiciona TODOS os arquivos de áudio da pasta atual.
 75 |    */
 76 |   const handleAddAll = useCallback(() => {
 77 |     const audioFiles = state.items.filter(isAudioFile) as DriveFile[];
 78 |     if (audioFiles.length === 0) return;
 79 | 
 80 |     const tracks = driveFilesToTracks(audioFiles);
 81 |     onAddTracks(tracks);
 82 |   }, [state.items, driveFilesToTracks, onAddTracks]);
 83 | 
 84 |   /**
 85 |    * Dispara busca.
 86 |    */
 87 |   const handleSearch = useCallback(
 88 |     (e: React.FormEvent) => {
 89 |       e.preventDefault();
 90 |       if (searchQuery.trim()) {
 91 |         searchAudio(searchQuery.trim());
 92 |       }
 93 |     },
 94 |     [searchQuery, searchAudio]
 95 |   );
 96 | 
 97 |   /**
 98 |    * Formata tamanho do arquivo.
 99 |    */
100 |   const formatSize = (bytes?: number): string => {
101 |     if (!bytes) return "";
102 |     const units = ["B", "KB", "MB", "GB"];
103 |     let value = bytes;
104 |     let unitIndex = 0;
105 |     while (value >= 1024 && unitIndex < units.length - 1) {
106 |       value /= 1024;
107 |       unitIndex++;
108 |     }
109 |     return `${value.toFixed(1)} ${units[unitIndex]}`;
110 |   };
111 | 
112 |   /**
113 |    * Formata data.
114 |    */
115 |   const formatDate = (dateStr?: string): string => {
116 |     if (!dateStr) return "";
117 |     const date = new Date(dateStr);
118 |     return date.toLocaleDateString("pt-BR", {
119 |       day: "2-digit",
120 |       month: "2-digit",
121 |       year: "numeric",
122 |     });
123 |   };
124 | 
125 |   // --- Renderização condicional ---
126 | 
127 |   // Se não tem Client ID configurado
128 |   if (!CLIENT_ID) {
129 |     return (
130 |       <div className="drive-panel">
131 |         <div className="panel-header">☁️ GOOGLE DRIVE</div>
132 |         <div className="drive-config-warning">
133 |           <p>⚠️ Google Drive não configurado</p>
134 |           <p className="drive-config-hint">
135 |             Crie um arquivo <code>.env</code> na raiz do projeto com:
136 |           </p>
137 |           <pre className="drive-config-code">
138 |             VITE_GOOGLE_CLIENT_ID=seu-client-id.apps.googleusercontent.com
139 |           </pre>
140 |           <p className="drive-config-hint">
141 |             Obtenha um Client ID no{" "}
142 |             <a
143 |               href="https://console.cloud.google.com/apis/credentials"
144 |               target="_blank"
145 |               rel="noopener noreferrer"
146 |             >
147 |               Google Cloud Console
148 |             </a>
149 |             , ative a Google Drive API e configure o redirect URI para
150 |             seu domínio (ex: http://localhost:1420).
151 |           </p>
152 |         </div>
153 |       </div>
154 |     );
155 |   }
156 | 
157 |   // Estado de carregamento inicial
158 |   if (state.isLoading && !state.isAuthenticated) {
159 |     return (
160 |       <div className="drive-panel">
161 |         <div className="panel-header">☁️ GOOGLE DRIVE</div>
162 |         <div className="drive-loading">
163 |           <span className="drive-spinner" />
164 |           <span>Conectando ao Google Drive...</span>
165 |         </div>
166 |       </div>
167 |     );
168 |   }
169 | 
170 |   // Não autenticado — tela de login
171 |   if (!state.isAuthenticated) {
172 |     return (
173 |       <div className="drive-panel">
174 |         <div className="panel-header">☁️ GOOGLE DRIVE</div>
175 |         <div className="drive-login">
176 |           <p className="drive-login-text">
177 |             Conecte-se ao Google Drive para acessar suas músicas.
178 |           </p>
179 |           <button
180 |             className="drive-login-btn"
181 |             onClick={login}
182 |             disabled={disabled}
183 |           >
184 |             ☁️ Entrar com Google
185 |           </button>
186 |           {state.error && (
187 |             <p className="drive-error">{state.error}</p>
188 |           )}
189 |         </div>
190 |       </div>
191 |     );
192 |   }
193 | 
194 |   // Autenticado — navegador do Drive
195 |   const audioCount = state.items.filter(isAudioFile).length;
196 |   const selectedCount = selectedFiles.size;
197 | 
198 |   return (
199 |     <div className="drive-panel">
200 |       <div className="panel-header">
201 |         <span>☁️ GOOGLE DRIVE</span>
202 |         <div className="drive-user-info">
203 |           {state.user?.picture && (
204 |             <img
205 |               src={state.user.picture}
206 |               alt=""
207 |               className="drive-user-avatar"
208 |             />
209 |           )}
210 |           <span className="drive-user-name">{state.user?.name}</span>
211 |           <button
212 |             className="drive-logout-btn"
213 |             onClick={logout}
214 |             title="Sair do Google Drive"
215 |           >
216 |             ✕
217 |           </button>
218 |         </div>
219 |       </div>
220 | 
221 |       {/* Breadcrumb */}
222 |       <div className="drive-breadcrumbs">
223 |         <button
224 |           className="drive-breadcrumb-btn"
225 |           onClick={() => navigateToBreadcrumb(-1)}
226 |           title="Raiz do Drive"
227 |         >
228 |           🏠
229 |         </button>
230 |         {state.breadcrumbs.map((folder, index) => (
231 |           <span key={folder.id} className="drive-breadcrumb-segment">
232 |             <span className="drive-breadcrumb-sep">/</span>
233 |             <button
234 |               className="drive-breadcrumb-btn"
235 |               onClick={() => navigateToBreadcrumb(index)}
236 |             >
237 |               {folder.name}
238 |             </button>
239 |           </span>
240 |         ))}
241 |         {state.currentFolder && (
242 |           <span className="drive-breadcrumb-segment">
243 |             <span className="drive-breadcrumb-sep">/</span>
244 |             <span className="drive-breadcrumb-current">
245 |               {state.currentFolder.name}
246 |             </span>
247 |           </span>
248 |         )}
249 |       </div>
250 | 
251 |       {/* Barra de busca */}
252 |       <form className="drive-search" onSubmit={handleSearch}>
253 |         <input
254 |           type="text"
255 |           className="drive-search-input"
256 |           placeholder="Buscar músicas..."
257 |           value={searchQuery}
258 |           onChange={(e) => setSearchQuery(e.target.value)}
259 |         />
260 |         <button type="submit" className="drive-search-btn" title="Buscar">
261 |           🔍
262 |         </button>
263 |       </form>
264 | 
265 |       {/* Ações em massa */}
266 |       <div className="drive-actions">
267 |         <span className="drive-item-count">
268 |           {audioCount} áudio{audioCount !== 1 ? "s" : ""}
269 |           {state.items.length > audioCount &&
270 |             ` · ${state.items.length - audioCount} pasta${state.items.length - audioCount !== 1 ? "s" : ""}`}
271 |         </span>
272 |         <div className="drive-action-btns">
273 |           {state.breadcrumbs.length > 0 && (
274 |             <button
275 |               className="drive-action-btn"
276 |               onClick={goUp}
277 |               title="Subir um nível"
278 |             >
279 |               ⬆ Subir
280 |             </button>
281 |           )}
282 |           {audioCount > 0 && (
283 |             <button
284 |               className="drive-action-btn"
285 |               onClick={handleAddAll}
286 |               disabled={disabled}
287 |               title="Adicionar todos os áudios à playlist"
288 |             >
289 |               📥 Todos
290 |             </button>
291 |           )}
292 |           {selectedCount > 0 && (
293 |             <button
294 |               className="drive-action-btn drive-action-btn-primary"
295 |               onClick={handleAddSelected}
296 |               disabled={disabled || isAdding}
297 |               title={`Adicionar ${selectedCount} arquivo${selectedCount !== 1 ? "s" : ""} selecionado${selectedCount !== 1 ? "s" : ""}`}
298 |             >
299 |               {isAdding ? "⏳" : `📥 +${selectedCount}`}
300 |             </button>
301 |           )}
302 |         </div>
303 |       </div>
304 | 
305 |       {/* Lista de arquivos */}
306 |       <div className="drive-file-list">
307 |         {state.isLoading ? (
308 |           <div className="drive-loading">
309 |             <span className="drive-spinner" />
310 |             <span>Carregando...</span>
311 |           </div>
312 |         ) : state.items.length === 0 ? (
313 |           <div className="drive-empty">
314 |             {searchQuery
315 |               ? "Nenhum resultado encontrado"
316 |               : "Esta pasta está vazia"}
317 |           </div>
318 |         ) : (
319 |           <ul className="drive-items">
320 |             {state.items.map((item) => {
321 |               const itemAny = item as any;
322 |               const isFolderItem = itemAny.mimeType === "application/vnd.google-apps.folder";
323 |               const isAudio = isAudioFile(item);
324 |               const isSelected = selectedFiles.has(itemAny.id);
325 | 
326 |               if (isFolderItem) {
327 |                 return (
328 |                   <li
329 |                     key={itemAny.id}
330 |                     className="drive-item drive-item-folder"
331 |                     onClick={() => navigateToFolder(item as unknown as DriveFolder)}
332 |                     title={`Abrir pasta ${itemAny.name}`}
333 |                   >
334 |                     <span className="drive-item-icon">📁</span>
335 |                     <span className="drive-item-name">{itemAny.name}</span>
336 |                   </li>
337 |                 );
338 |               }
339 | 
340 |               if (!isAudio) {
341 |                 return (
342 |                   <li key={itemAny.id} className="drive-item drive-item-other">
343 |                     <span className="drive-item-icon">📄</span>
344 |                     <span className="drive-item-name">{itemAny.name}</span>
345 |                   </li>
346 |                 );
347 |               }
348 | 
349 |               // Arquivo de áudio
350 |               return (
351 |                 <li
352 |                   key={itemAny.id}
353 |                   className={`drive-item drive-item-audio ${
354 |                     isSelected ? "drive-item-selected" : ""
355 |                   }`}
356 |                   onClick={() => toggleSelect(itemAny.id)}
357 |                 >
358 |                   <span className="drive-item-checkbox">
359 |                     {isSelected ? "☑" : "☐"}
360 |                   </span>
361 |                   <span className="drive-item-icon">🎵</span>
362 |                   <span className="drive-item-name">{itemAny.name}</span>
363 |                   <span className="drive-item-size">
364 |                     {formatSize(itemAny.size)}
365 |                   </span>
366 |                   <span className="drive-item-date">
367 |                     {formatDate(itemAny.modifiedTime)}
368 |                   </span>
369 |                 </li>
370 |               );
371 |             })}
372 |           </ul>
373 |         )}
374 |       </div>
375 | 
376 |       {state.error && (
377 |         <div className="drive-error-bar">
378 |           <span>⚠️ {state.error}</span>
379 |         </div>
380 |       )}
381 |     </div>
382 |   );
383 | }
